import math

def chernoff_poisson(lambda_, k):
    if lambda_ == 0:
        return 0.0
    if k <= lambda_:
        return 1.0

    delta = k / lambda_ - 1.0

    log_term = delta - (1.0 + delta) * math.log(1.0 + delta)
    return math.exp(lambda_ * log_term)

